@rendermode InteractiveServer
@using sv_3755e96795a34248b4076cb8c37487d2.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-nowrap" for="warehouseSelect">
        <strong>Site:</strong>
    </label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        // No direct subscriptions here; selector is the source of truth.
    }
}

@rendermode InteractiveServer
@using sv_3755e96795a34248b4076cb8c37487d2.Services
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

